#include <cstdio>
#include <cstdlib>
#include <cstring>

struct FileRecord {
    char* data;
    size_t len;
};

void process_file(FileRecord* rec) {
    if (!rec || !rec->data) return;
    if (rec->len > 1024) {
        free(rec->data);
        rec->data = NULL;
        return;
    }
    // line 12: use after potential free
    printf("data: %s\n", rec->data);
    free(rec->data);
    // line 15: second free
    free(rec->data);
}

int main() {
    FileRecord rec;
    rec.len = 2048;
    rec.data = (char*)malloc(rec.len);
    strcpy(rec.data, "test");
    process_file(&rec);
    return 0;
}
```

**分析过程（路径B：模式识别优先）**

1. 第12行`free(rec->data)`后未置NULL，第15行再次`free`，构成double free模式。
2. 第7行`if (rec->len > 1024)`提前释放并置NULL，但第12-15行路径未覆盖此防御。
3. 排除反例：无有效引用计数或所有权转移，两处`free`均直接操作同一指针。
4. 结论：CWE-415，双释放导致堆破坏。

