#include <stdlib.h>
#include <string.h>
#include <stdio.h>

typedef struct {
    char *data;
    int len;
} Packet;

Packet *parse_packet(const char *buf, size_t size) {
    Packet *pkt = malloc(sizeof(Packet));
    pkt->data = malloc(size);
    memcpy(pkt->data, buf, size);
    pkt->len = size;
    return pkt;
}

void process_packet(Packet *pkt) {
    if (pkt->len > 10) {
        free(pkt->data);
        printf("Size: %d\n", pkt->len);  // line 17: UAF - data freed, still accessed
    }
}

int main() {
    char raw[20] = {0};
    Packet *p = parse_packet(raw, 20);
    process_packet(p);
    free(p);
    return 0;
}
```

**分析过程（路径A：数据流优先）**
1. line 17: 若len>10，free(pkt->data)后立即使用pkt->len — UAF模式
2. line 10: 数据分配并复制，line 14: 传入process_packet — 数据流清晰
3. 无防御：free后未置NULL，也无引用计数
4. 结论：CWE-416，访问已释放内存

