#include <pthread.h>
#include <stdlib.h>
#include <unistd.h>

struct Data { int id; char *buf; };

void *worker(void *arg) {
    struct Data *d = (struct Data*)arg;
    usleep(1000); // simulate work
    printf("%s\n", d->buf); // line 10
    return NULL;
}

void cleanup(struct Data *d) {
    if (d->buf) free(d->buf); // line 15
    free(d);
}

int main() {
    pthread_t t;
    struct Data *d = malloc(sizeof(*d));
    d->buf = malloc(64);
    pthread_create(&t, NULL, worker, d); // line 22
    cleanup(d); // line 23
    pthread_join(t, NULL);
    return 0;
}
```

**分析过程**
1. 路径A：source为d->buf堆内存，line 22传入线程
2. sink为line 10读d->buf，line 15释放
3. 数据流：line 22创建线程→line 23主线程释放→line 10可能读已释放内存
4. 防御评估：无同步机制，free后未置NULL，竞态触发UAF
5. 结论：CWE-416，Use-After-Free

